template <typename MaybeConstUserType>
struct Serializer<::ash::mojom::RemappingActionDataView, MaybeConstUserType> {
  using UserType = typename std::remove_const<MaybeConstUserType>::type;
  using Traits = UnionTraits<::ash::mojom::RemappingActionDataView, UserType>;

  static void Serialize(MaybeConstUserType& input,
                        MessageFragment<::ash::mojom::internal::RemappingAction_Data>& fragment,
                        bool inlined) {
    if (CallIsNullIfExists<Traits>(input)) {
       if (inlined)
        fragment->set_null();
      return;
    }

    if (!inlined)
      fragment.Allocate();

    // TODO(azani): Handle unknown and objects.
    // Set the not-null flag.
    fragment->size = kUnionDataSize;
    fragment->tag = Traits::GetTag(input);
    switch (fragment->tag) {
      case ::ash::mojom::RemappingActionDataView::Tag::kAcceleratorAction: {
        decltype(Traits::accelerator_action(input))
            in_accelerator_action = Traits::accelerator_action(input);
        mojo::internal::Serialize<::ash::mojom::AcceleratorAction>(
            in_accelerator_action, &fragment->data.f_accelerator_action);
        break;
      }
      case ::ash::mojom::RemappingActionDataView::Tag::kKeyEvent: {
        decltype(Traits::key_event(input))
            in_key_event = Traits::key_event(input);
        mojo::internal::MessageFragment<
            typename decltype(fragment->data.f_key_event)::BaseType>
            value_fragment(fragment.message());
        mojo::internal::Serialize<::ash::mojom::KeyEventDataView>(
            in_key_event, value_fragment);
        MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
            value_fragment.is_null(),
            mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
            "null key_event in RemappingAction union");
        fragment->data.f_key_event.Set(
            value_fragment.is_null() ? nullptr : value_fragment.data());
        break;
      }
      case ::ash::mojom::RemappingActionDataView::Tag::kStaticShortcutAction: {
        decltype(Traits::static_shortcut_action(input))
            in_static_shortcut_action = Traits::static_shortcut_action(input);
        mojo::internal::Serialize<::ash::mojom::StaticShortcutAction>(
            in_static_shortcut_action, &fragment->data.f_static_shortcut_action);
        break;
      }
    }
  }

  static bool Deserialize(::ash::mojom::internal::RemappingAction_Data* input,
                          UserType* output,
                          Message* message) {
    if (!input || input->is_null())
      return CallSetToNullIfExists<Traits>(output);

    ::ash::mojom::RemappingActionDataView data_view(input, message);
    return Traits::Read(data_view, output);
  }
};

